import React from 'react';
import { Settings } from 'lucide-react';

export function PropertiesPanel() {
    return (
        <div className="flex flex-col h-full">
            <div className="p-4 border-b border-gray-800 flex items-center gap-2">
                <Settings className="w-4 h-4 text-gray-400" />
                <h3 className="font-semibold text-gray-200">Properties</h3>
            </div>

            <div className="flex-1 p-6 flex flex-col items-center justify-center text-center text-gray-500">
                <div className="w-16 h-16 bg-gray-900 rounded-full flex items-center justify-center mb-4">
                    <Settings className="w-8 h-8 opacity-50" />
                </div>
                <p>Select an element to configure it</p>
            </div>
        </div>
    );
}
