'use client';

import React, { useState, useRef } from 'react';
import {
    DndContext,
    DragOverlay,
    useDraggable,
    useDroppable,
    DragStartEvent,
    DragEndEvent,
    DragOverEvent,
    MouseSensor,
    TouchSensor,
    useSensor,
    useSensors
} from '@dnd-kit/core';
import { MainLayout } from '@/components/layout/MainLayout';
import { PropertiesPanel } from '../PropertiesPanel';
import { createPortal } from 'react-dom';

// Types
export interface CanvasItemData {
    id: string;
    type: string;
    x: number;
    y: number;
    label: string;
}

// Draggable Sidebar Item
function DraggableSidebarItem({ type, label }: { type: string, label: string }) {
    const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
        id: `sidebar-${type}-${label}`,
        data: { type, label, source: 'sidebar' }
    });

    return (
        <div
            ref={setNodeRef}
            {...listeners}
            {...attributes}
            className={`p-3 bg-gray-900 rounded-lg border border-gray-800 cursor-grab hover:border-blue-500 transition-colors ${isDragging ? 'opacity-50' : ''}`}
        >
            {label}
        </div>
    );
}

// Draggable Canvas Item (Already placed)
function DraggableCanvasItem({ item }: { item: CanvasItemData }) {
    const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
        id: item.id,
        data: { ...item, source: 'canvas' }
    });

    const style = {
        position: 'absolute' as const,
        top: item.y,
        left: item.x,
        opacity: isDragging ? 0 : 1, // Hide original while dragging (overlay shows)
    };

    return (
        <div
            ref={setNodeRef}
            style={style}
            {...listeners}
            {...attributes}
            className="p-3 w-40 bg-gray-800 rounded-lg border border-blue-500/30 text-center shadow-lg cursor-move hover:border-blue-500 transition-colors z-10"
        >
            {item.label}
        </div>
    );
}

// Canvas Droppable Area
function CanvasDroppable({ items, canvasRef }: { items: CanvasItemData[], canvasRef: React.RefObject<HTMLDivElement | null> }) {
    const { setNodeRef } = useDroppable({
        id: 'canvas-droppable',
    });

    // Merge refs
    const setRefs = (node: HTMLDivElement) => {
        setNodeRef(node);
        if (canvasRef) {
            (canvasRef as any).current = node;
        }
    };

    return (
        <div ref={setRefs} className="w-full h-full relative min-h-screen p-8 overflow-hidden">
            <div className="absolute inset-0 pointer-events-none opacity-20 bg-[linear-gradient(to_right,#80808012_1px,transparent_1px),linear-gradient(to_bottom,#80808012_1px,transparent_1px)] bg-[size:24px_24px]"></div>

            {items.map((item) => (
                <DraggableCanvasItem key={item.id} item={item} />
            ))}

            {items.length === 0 && (
                <div className="absolute inset-0 flex items-center justify-center text-gray-600 pointer-events-none">
                    Drag items here
                </div>
            )}
        </div>
    );
}

export function CanvasBoard() {
    const [items, setItems] = useState<CanvasItemData[]>([]);
    const [activeDragItem, setActiveDragItem] = useState<any>(null);
    const [mounted, setMounted] = useState(false);
    const canvasRef = useRef<HTMLDivElement>(null);

    React.useEffect(() => {
        setMounted(true);
    }, []);

    const sensors = useSensors(
        useSensor(MouseSensor, { activationConstraint: { distance: 10 } }),
        useSensor(TouchSensor, { activationConstraint: { delay: 250, tolerance: 5 } })
    );

    const handleDragStart = (event: DragStartEvent) => {
        setActiveDragItem(event.active.data.current);
    };

    const handleDragEnd = (event: DragEndEvent) => {
        const { active, over } = event;
        setActiveDragItem(null);

        if (!over) return;

        if (active.data.current?.source === 'sidebar' && over.id === 'canvas-droppable') {
            // New item drop
            const canvasRect = canvasRef.current?.getBoundingClientRect();
            const droppedRect = active.rect.current.translated;

            if (canvasRect && droppedRect) {
                const newItem: CanvasItemData = {
                    id: `item-${Date.now()}`,
                    type: active.data.current.type,
                    label: active.data.current.label,
                    x: droppedRect.left - canvasRect.left + 24, // + offset to center or align? using raw drops for now
                    y: droppedRect.top - canvasRect.top,
                };
                setItems((prev) => [...prev, newItem]);
            }
        } else if (active.data.current?.source === 'canvas') {
            // Moving existing item
            const canvasRect = canvasRef.current?.getBoundingClientRect();
            const droppedRect = active.rect.current.translated;

            if (canvasRect && droppedRect) {
                setItems((prev) => prev.map(item => {
                    if (item.id === active.id) {
                        return {
                            ...item,
                            x: droppedRect.left - canvasRect.left,
                            y: droppedRect.top - canvasRect.top
                        };
                    }
                    return item;
                }));
            }
        }
    };

    return (
        <DndContext sensors={sensors} onDragStart={handleDragStart} onDragEnd={handleDragEnd}>
            <MainLayout
                sidebar={
                    <div className="p-4 space-y-4">
                        <h2 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-indigo-400 mb-6">
                            Qanvas
                        </h2>
                        <div className="space-y-4">
                            <h3 className="text-sm font-semibold text-gray-400">Vendors</h3>
                            <DraggableSidebarItem type="vendor" label="VMware" />
                            <DraggableSidebarItem type="vendor" label="Microsoft" />
                            <DraggableSidebarItem type="vendor" label="AWS" />

                            <h3 className="text-sm font-semibold text-gray-400 pt-4">Products</h3>
                            <DraggableSidebarItem type="product" label="vSphere" />
                            <DraggableSidebarItem type="product" label="Azure Virtual Desktop" />
                        </div>
                    </div>
                }
                canvas={<CanvasDroppable items={items} canvasRef={canvasRef} />}
                propertiesPanel={<PropertiesPanel />}
            />
            {mounted && createPortal(
                <DragOverlay>
                    {activeDragItem ? (
                        <div className="p-3 bg-gray-800 rounded-lg border border-blue-500 shadow-xl opacity-80 w-40 text-center text-white z-50 pointer-events-none">
                            {activeDragItem.label}
                        </div>
                    ) : null}
                </DragOverlay>,
                document.body
            )}
        </DndContext>
    );
}
